/**
 * Pulse Build 0.3.0 — one-time accepted weekly identity registry installer.
 *
 * This hidden engineering registry persists the exact identity candidates
 * approved by the 84-week preflight. It does not modify Pulse catalogs,
 * mappings, facts, cache authority, Performance, Reports, or source files.
 */
function main(workbook: ExcelScript.Workbook): IdentityRegistryInstallResult {
  validateActiveCheckpoint(workbook);
  const existing = workbook.getWorksheet(SHEET_NAME);
  if (existing) {
    validateInstalledRegistry(workbook);
    return result("Already installed");
  }
  const sheet = workbook.addWorksheet(SHEET_NAME);
  try {
    sheet.setVisibility(ExcelScript.SheetVisibility.hidden);
    createTable(sheet, 0, CONTROL_HEADERS, [[REGISTRY_VERSION, EXPECTED_IDP,
      EXPECTED_WIR, RESTAURANTS.length, CLASSIFICATIONS.length, PRODUCTS.length]], TABLES[0]);
    createTable(sheet, 4, RESTAURANT_HEADERS, RESTAURANTS, TABLES[1]);
    createTable(sheet, 4 + RESTAURANTS.length + 3, CLASSIFICATION_HEADERS,
      CLASSIFICATIONS, TABLES[2]);
    createTable(sheet, 4 + RESTAURANTS.length + 3 + CLASSIFICATIONS.length + 3,
      PRODUCT_HEADERS, PRODUCTS, TABLES[3]);
    validateInstalledRegistry(workbook);
    return result("Installed");
  } catch (error) {
    try { sheet.delete(); } catch (ignored) { /* best-effort rollback */ }
    throw new Error(`PUL-030WIR-001: Identity registry installation failed. ${String(error)}`);
  }
}

type CellValue = string | number | boolean;
interface IdentityRegistryInstallResult {
  status: string; identityPreflightFingerprint: string;
  identityRegistryFingerprint: string; restaurantCount: number;
  classificationCount: number; productCount: number;
}

