function validateActiveCheckpoint(workbook: ExcelScript.Workbook): void {
  const table = workbook.getTable("tblWeeklyCacheVersions");
  if (!table) throw new Error("PUL-030WIR-002: tblWeeklyCacheVersions is missing.");
  const headers = table.getHeaderRowRange().getTexts()[0];
  const values = table.getRangeBetweenHeaderAndTotal().getTexts();
  const version = headers.indexOf("CacheVersion"); const status = headers.indexOf("CacheStatus");
  const authority = headers.indexOf("ActivationState");
  const validation = headers.indexOf("ValidationStatus");
  const identity = headers.indexOf("IdentityPreflightFingerprint");
  const active: string[][] = [];
  for (const row of values) if (row[status] === "Active" && row[authority] === "Active") active.push(row);
  if (active.length !== 1 || active[0][version] !== EXPECTED_ACTIVE_VERSION ||
      active[0][validation] !== "PASS" || active[0][identity] !== EXPECTED_IDP) {
    throw new Error("PUL-030WIR-003: Active weekly checkpoint differs from the accepted 84-week identity evidence.");
  }
}

function validateInstalledRegistry(workbook: ExcelScript.Workbook): void {
  const sheet = workbook.getWorksheet(SHEET_NAME);
  if (!sheet || sheet.getVisibility() !== ExcelScript.SheetVisibility.hidden) {
    throw new Error("PUL-030WIR-004: Identity registry sheet is missing or visible.");
  }
  const control = requiredTable(workbook, TABLES[0]).getRangeBetweenHeaderAndTotal().getValues();
  const restaurants = requiredTable(workbook, TABLES[1]).getRangeBetweenHeaderAndTotal().getValues();
  const classifications = requiredTable(workbook, TABLES[2]).getRangeBetweenHeaderAndTotal().getValues();
  const products = requiredTable(workbook, TABLES[3]).getRangeBetweenHeaderAndTotal().getValues();
  if (control.length !== 1 || String(control[0][0]) !== REGISTRY_VERSION ||
      String(control[0][1]) !== EXPECTED_IDP || String(control[0][2]) !== EXPECTED_WIR ||
      Number(control[0][3]) !== RESTAURANTS.length || Number(control[0][4]) !== CLASSIFICATIONS.length ||
      Number(control[0][5]) !== PRODUCTS.length || restaurants.length !== RESTAURANTS.length ||
      classifications.length !== CLASSIFICATIONS.length || products.length !== PRODUCTS.length) {
    throw new Error("PUL-030WIR-005: Installed identity registry control/counts differ.");
  }
  if (fingerprint(restaurants, classifications, products) !== EXPECTED_WIR) {
    throw new Error("PUL-030WIR-006: Installed identity registry content differs.");
  }
}

function fingerprint(restaurants: CellValue[][], classifications: CellValue[][],
  products: CellValue[][]): string {
  const records = [record("CONTRACT", [REGISTRY_VERSION])];
  for (const row of restaurants) records.push(record("RESTAURANT", row));
  for (const row of classifications) records.push(record("CLASSIFICATION", row));
  for (const row of products) {
    const values = row.slice(0, 8); const paths = String(row[8] || "").split("\u001f")
      .filter(value => value !== "").sort(compareText);
    for (const path of paths) values.push(path);
    records.push(record("PRODUCT", values));
  }
  records.sort(compareText);
  return hashStrings(records, "WIR-");
}

function createTable(sheet: ExcelScript.Worksheet, startRow: number, headers: string[],
  rows: CellValue[][], name: string): void {
  sheet.getRangeByIndexes(startRow, 0, 1, headers.length).setValues([headers]);
  const chunk = 500;
  for (let offset = 0; offset < rows.length; offset += chunk) {
    const part = rows.slice(offset, Math.min(rows.length, offset + chunk));
    sheet.getRangeByIndexes(startRow + 1 + offset, 0, part.length, headers.length).setValues(part);
  }
  const table = sheet.addTable(sheet.getRangeByIndexes(startRow, 0, rows.length + 1,
    headers.length), true);
  table.setName(name); table.setPredefinedTableStyle("TableStyleMedium2");
}

function requiredTable(workbook: ExcelScript.Workbook, name: string): ExcelScript.Table {
  const table = workbook.getTable(name); if (!table) throw new Error(`PUL-030WIR-007: ${name} is missing.`);
  return table;
}
function result(status: string): IdentityRegistryInstallResult {
  return { status, identityPreflightFingerprint: EXPECTED_IDP,
    identityRegistryFingerprint: EXPECTED_WIR, restaurantCount: RESTAURANTS.length,
    classificationCount: CLASSIFICATIONS.length, productCount: PRODUCTS.length };
}
function record(kind: string, values: CellValue[]): string {
  return `${kind}|${values.map(value => { const normalized = value === null || value === undefined ? "" : String(value); return `${normalized.length}:${normalized}`; }).join("|")}`;
}
function hashStrings(values: string[], prefix: string): string {
  let left = 0; let right = 0;
  for (const item of values) { const value = `${item}\n`; for (let index = 0; index < value.length; index += 1) {
    const code = value.charCodeAt(index); left = (left * 131 + code) % 2147483647;
    right = (right * 137 + code) % 2147483629;
  } }
  return `${prefix}${left.toString(16).padStart(8, "0")}${right.toString(16).padStart(8, "0")}`;
}
function compareText(left: CellValue, right: CellValue): number {
  const a = String(left); const b = String(right); return a < b ? -1 : a > b ? 1 : 0;
}
